'use client'

import { ChangeEvent, FormEvent, useCallback, useEffect, useMemo, useState } from 'react'
import { Activity, AlertTriangle, ArrowRight, CheckCircle2, CircleDot, Database, FileUp, GitBranch, History, Loader2, Network, Play, RefreshCw, Search, ShieldAlert, SlidersHorizontal, Sparkles, Target, Upload, X } from 'lucide-react'

type ApiError = { code: string; message: string; details?: Record<string, unknown>; suggestedActions?: string[]; requestId?: string }
type ApiResponse<T> = { success: true; data: T; requestId: string } | { success: false; error: ApiError; requestId: string }
type Dataset = { id: string; name: string; description?: string | null; provider: string; category?: string | null; nodeCount: number; edgeCount: number; isTemporal: boolean; isDirected: boolean; isWeighted: boolean; status: string; storage: string; compatibility: string; sizeBytes?: string | null; isCatalog: boolean; isUserUpload: boolean; isProjectCopy: boolean; provenance?: unknown; _count?: { nodes: number; dependencies: number } }
type Node = { id: string; name: string; code: string; type: string; status: string; criticality: number; health: number; capacity: number; currentLoad: number; observations?: Array<{ metric: string; value: number; unit: string; observedAt: string; source: string }> }
type Dependency = { id: string; fromNodeId: string; toNodeId: string; strength: number; propagationProbability: number; propagationDelay: number; relationship: string }
type Prediction = { id: string; probability: number; riskScore: number; impactScore: number; confidence: number; criticalEndpoints: number; timeToImpact: number; reasoning: string; createdAt: string; paths: Array<{ id: string; hop: number; delayMinutes: number; probability: number; reason: string; node: { id: string; name: string; code: string } }> }
type Dashboard = { project: { id: string; name: string }; activeDataset: (Dataset & { nodes: number; edges: number; observations: number }) | null; activeScenario: { id: string; name: string; triggerSeverity: number; events: Array<{ nodeId: string }> } | null; latestPrediction: Prediction | null; scenarios: Array<{ id: string; name: string; triggerSeverity: number; events: Array<{ nodeId: string }>; predictions: Array<Prediction> }>; recentRuns: Array<{ id: string; modelName: string; isBaseline: boolean; startedAt: string; scenario: { id: string; name: string }; results: Array<{ id: string }> }>; datasetCount: number; diagnostics: Diagnostic[]; model: { name: string; version: string; type: string } }
type Diagnostic = { id: string; severity: string; component: string; operation: string; message: string; technicalDetails?: string | null; parameters?: Record<string, unknown> | null; suggestedFix?: string | null; requestId?: string | null; createdAt: string; resolved: boolean }
type Health = { database: { status: string; latencyMs: number; datasets: number; projects: number }; api: { status: string }; datasetStorage: { status: string; mode: string }; cascadeEngine: { status: string; model: string }; simulationEngine: { status: string }; ingestionEngine: { status: string }; checkedAt: string }
type DatasetDetail = Dataset & { schemas: Array<{ fields: Array<{ name: string; inferredType: string; nullable: boolean; sample: string | null }> }>; mappings: Array<{ id: string; name: string; mapping: { source?: string; target?: string; timestamp?: string; weight?: string; label?: string }; isActive: boolean }>; files: Array<{ originalName: string; sizeBytes: string; checksum: string }>; imports: Array<{ id: string; status: string; rowCount: number; bytesRead: string; bytesTotal?: string | null; errorMessage?: string | null }> }
type ScenarioDetail = { id: string; name: string; triggerSeverity: number; events: Array<{ node: { id: string; name: string } }>; predictions: Prediction[]; runs: Array<{ id: string; isBaseline: boolean; status: string; modelName: string; results: Array<{ id: string; affected: boolean; probability: number; state: string; reason: string; timeOffset: number; node: { name: string; criticality: number } }> }>; interventions: Array<{ id: string; name: string; description: string; status: string; cost: number; feasibility: number; expectedReduction: number; candidates: Array<{ score: number; riskReduction: number; criticalityProtected: number; coverage: number; rationale: string }> }> }

class ClientApiError extends Error {
  constructor(public payload: ApiError) { super(payload.message) }
}

async function api<T>(url: string, init?: RequestInit): Promise<T> {
  const response = await fetch(url, { ...init, headers: init?.body instanceof FormData ? init.headers : { 'content-type': 'application/json', ...init?.headers } })
  const body = await response.json().catch(() => null) as ApiResponse<T> | null
  if (!response.ok || !body || !body.success) throw new ClientApiError(body && !body.success ? { ...body.error, requestId: body.requestId } : { code: 'NETWORK_RESPONSE_INVALID', message: 'The server returned an unreadable response.', suggestedActions: ['Check server logs and retry.'] })
  return body.data
}

function percentage(value: number) { return `${Math.round(value * 100)}%` }
function number(value: number | undefined | null) { return new Intl.NumberFormat().format(value ?? 0) }
function formatBytes(value?: string | null) { if (!value) return 'Unknown'; const bytes = Number(value); return bytes < 1024 * 1024 ? `${Math.round(bytes / 1024)} KB` : `${(bytes / (1024 * 1024)).toFixed(1)} MB` }
function statusTone(status?: string) { return status === 'ONLINE' || status === 'IMPORTED' || status === 'READY' || status === 'COMPLETED' || status === 'APPLIED' ? 'text-emerald-300 border-emerald-300/20 bg-emerald-300/5' : status === 'FAILED' || status === 'OFFLINE' || status === 'NOT_COMPATIBLE' ? 'text-red-200 border-red-300/20 bg-red-300/5' : 'text-amber-200 border-amber-300/20 bg-amber-300/5' }

export default function Page() {
  const [view, setView] = useState<'Command Center' | 'Dataset Library' | 'Network Editor' | 'Cascade Simulator' | 'Scenario History' | 'Diagnostics Center'>('Command Center')
  const [dashboard, setDashboard] = useState<Dashboard | null>(null)
  const [health, setHealth] = useState<Health | null>(null)
  const [datasets, setDatasets] = useState<Dataset[]>([])
  const [network, setNetwork] = useState<{ nodes: Node[]; dependencies: Dependency[] } | null>(null)
  const [selectedDataset, setSelectedDataset] = useState<DatasetDetail | null>(null)
  const [selectedScenario, setSelectedScenario] = useState<ScenarioDetail | null>(null)
  const [diagnostic, setDiagnostic] = useState<ApiError | Diagnostic | null>(null)
  const [loading, setLoading] = useState(true)
  const [busy, setBusy] = useState<string | null>(null)
  const [search, setSearch] = useState('')

  const reportError = useCallback((error: unknown) => {
    if (error instanceof ClientApiError) setDiagnostic(error.payload)
    else setDiagnostic({ code: 'CLIENT_OPERATION_FAILED', message: 'The interface could not complete the requested operation.', details: { operation: 'interface action', technicalDetails: error instanceof Error ? error.message : String(error) }, suggestedActions: ['Retry the operation. If this continues, inspect the server logs.'] })
  }, [])

  const refresh = useCallback(async (includeCatalog = false) => {
    setLoading(true)
    try {
      const [healthData, dashboardData, datasetData] = await Promise.all([api<Health>('/api/health'), api<Dashboard>('/api/dashboard'), api<Dataset[]>(`/api/datasets${includeCatalog && search ? `?q=${encodeURIComponent(search)}` : ''}`)])
      setHealth(healthData); setDashboard(dashboardData); setDatasets(datasetData)
      if (dashboardData.activeDataset) {
        const graph = await api<{ nodes: Node[]; dependencies: Dependency[] }>('/api/network')
        setNetwork(graph)
      } else setNetwork(null)
    } catch (error) { reportError(error) } finally { setLoading(false) }
  }, [reportError, search])

  useEffect(() => { void refresh() }, [refresh])

  const runAction = useCallback(async (label: string, operation: () => Promise<void>) => {
    setBusy(label)
    try { await operation() } catch (error) { reportError(error) } finally { await refresh(true); setBusy(null) }
  }, [refresh, reportError])

  const openDataset = async (id: string) => {
    setBusy(`open-${id}`)
    try { setSelectedDataset(await api<DatasetDetail>(`/api/datasets/${id}`)); setView('Dataset Library') } catch (error) { reportError(error) } finally { setBusy(null) }
  }
  const openScenario = async (id: string) => {
    setBusy(`scenario-${id}`)
    try { setSelectedScenario(await api<ScenarioDetail>(`/api/scenarios/${id}`)); setView('Cascade Simulator') } catch (error) { reportError(error) } finally { setBusy(null) }
  }
  const activeDataset = dashboard?.activeDataset ?? null

  return <main className="min-h-screen bg-[#071014] text-[#dce9e9]">
    <div className="flex min-h-screen">
      <aside className="hidden w-72 shrink-0 flex-col border-r border-white/8 bg-[#09161a] p-5 lg:flex">
        <div className="mb-10 flex items-center gap-3 px-2"><div className="grid size-9 place-items-center rounded-xl border border-cyan-300/30 bg-cyan-300/10 text-cyan-300"><GitBranch className="size-5" /></div><div><p className="font-mono text-sm font-bold tracking-[.18em] text-white">CHAIN</p><p className="font-mono text-[9px] tracking-[.28em] text-cyan-300/70">REACTION</p></div></div>
        <p className="mb-3 px-2 font-mono text-[10px] uppercase tracking-[.2em] text-slate-500">Operations</p>
        <nav className="space-y-1">{([
          ['Command Center', Activity], ['Dataset Library', Database], ['Network Editor', Network], ['Cascade Simulator', Play], ['Scenario History', History], ['Diagnostics Center', ShieldAlert],
        ] as const).map(([label, Icon]) => <button key={label} onClick={() => setView(label)} className={`flex w-full items-center gap-3 rounded-lg px-3 py-3 text-left text-sm ${view === label ? 'bg-cyan-300/10 text-cyan-200 ring-1 ring-cyan-300/15' : 'text-slate-400 hover:bg-white/5 hover:text-white'}`}><Icon className="size-4" />{label}</button>)}</nav>
        <div className="mt-auto rounded-xl border border-cyan-300/15 bg-cyan-300/5 p-4"><div className="mb-3 flex items-center gap-2 text-xs text-cyan-100"><Sparkles className="size-4 text-cyan-300" />{dashboard?.model.name ?? 'Model unverified'}</div><p className="text-xs leading-5 text-slate-400">{dashboard?.model.type ?? 'Waiting for database health verification.'}</p><div className={`mt-4 flex items-center gap-2 font-mono text-[10px] ${health ? 'text-emerald-300' : 'text-amber-200'}`}><span className={`size-1.5 rounded-full ${health ? 'bg-emerald-400' : 'bg-amber-300'}`} />{health ? 'SERVER VERIFIED' : 'DATABASE UNVERIFIED'}</div></div>
      </aside>
      <section className="min-w-0 flex-1">
        <header className="flex min-h-16 items-center justify-between gap-4 border-b border-white/8 px-5 py-3 sm:px-8"><div><p className="font-mono text-[10px] uppercase tracking-[.18em] text-slate-500">{dashboard?.project.name ?? 'Chain Reaction'} / {view}</p><h1 className="text-sm font-semibold text-white">Predict the cascade. Stop it before it spreads.</h1></div><button onClick={() => void refresh(true)} disabled={Boolean(busy)} className="flex items-center gap-2 rounded-lg border border-white/10 px-3 py-2 text-xs text-slate-300 hover:bg-white/5 disabled:opacity-50"><RefreshCw className={`size-3.5 ${loading ? 'animate-spin' : ''}`} />Check system health</button></header>
        <div className="mx-auto max-w-[1540px] p-5 sm:p-8">
          {loading && !dashboard ? <LoadingState /> : view === 'Command Center' ? <CommandCenter dashboard={dashboard} health={health} network={network} onOpenDataset={() => setView('Dataset Library')} onOpenScenario={openScenario} /> : null}
          {view === 'Dataset Library' ? <DatasetLibrary datasets={datasets} selected={selectedDataset} search={search} setSearch={setSearch} busy={busy} openDataset={openDataset} onAction={runAction} refresh={refresh} /> : null}
          {view === 'Network Editor' ? <NetworkEditor network={network} activeDataset={activeDataset} onAction={runAction} /> : null}
          {view === 'Cascade Simulator' ? <Simulator dashboard={dashboard} network={network} scenario={selectedScenario} setScenario={setSelectedScenario} busy={busy} onAction={runAction} openScenario={openScenario} /> : null}
          {view === 'Scenario History' ? <ScenarioHistory dashboard={dashboard} onOpenScenario={openScenario} /> : null}
          {view === 'Diagnostics Center' ? <Diagnostics diagnostics={dashboard?.diagnostics ?? []} onOpen={(entry) => setDiagnostic(entry)} /> : null}
        </div>
      </section>
    </div>
    {diagnostic && <DiagnosticWindow diagnostic={diagnostic} onClose={() => setDiagnostic(null)} />}
  </main>
}

function LoadingState() { return <div className="grid min-h-[55vh] place-items-center"><div className="text-center"><Loader2 className="mx-auto size-8 animate-spin text-cyan-300" /><p className="mt-4 text-sm text-slate-300">Verifying the server and PostgreSQL state…</p><p className="mt-1 text-xs text-slate-500">No local fallback data is shown.</p></div></div> }

function SectionHeader({ eyebrow, title, description, children }: { eyebrow: string; title: string; description: string; children?: React.ReactNode }) { return <div className="mb-6 flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><p className="font-mono text-[10px] uppercase tracking-[.22em] text-cyan-300">{eyebrow}</p><h2 className="mt-2 text-3xl font-semibold tracking-tight text-white sm:text-4xl">{title}</h2><p className="mt-3 max-w-2xl text-sm leading-6 text-slate-400">{description}</p></div>{children}</div> }

function Pill({ value }: { value: string }) { return <span className={`inline-flex rounded-full border px-2 py-1 font-mono text-[9px] uppercase tracking-wide ${statusTone(value)}`}>{value.replaceAll('_', ' ')}</span> }

function CommandCenter({ dashboard, health, network, onOpenDataset, onOpenScenario }: { dashboard: Dashboard | null; health: Health | null; network: { nodes: Node[]; dependencies: Dependency[] } | null; onOpenDataset: () => void; onOpenScenario: (id: string) => void }) {
  const dataset = dashboard?.activeDataset; const prediction = dashboard?.latestPrediction
  return <div className="space-y-6"><SectionHeader eyebrow="Live command center" title="See the cascade before it starts." description="All metrics below are queried from the active PostgreSQL-backed project. Synthetic, imported, and user-authored provenance is shown explicitly."><button onClick={onOpenDataset} className="flex items-center gap-2 rounded-lg bg-cyan-300 px-4 py-2.5 text-xs font-semibold text-[#071014]"><Database className="size-4" />Dataset Library</button></SectionHeader>
    <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><MetricCard label="Cascade probability" value={prediction ? percentage(prediction.probability) : '—'} note={prediction ? 'latest completed run' : 'no completed simulation'} accent="risk" /><MetricCard label="Nodes at risk" value={prediction ? number(prediction.paths.length) : '—'} note={dataset ? `${number(dataset.nodes)} active nodes` : 'no active dataset'} /><MetricCard label="Critical endpoints" value={prediction ? number(prediction.criticalEndpoints) : '—'} note={prediction ? `first at T+${prediction.timeToImpact}` : 'run a scenario'} /><MetricCard label="Active dataset" value={dataset ? number(dataset.edges) : '—'} note={dataset ? `${dataset.name} · ${dataset.provider}` : 'select a compatible dataset'} /></div>
    <div className="grid gap-6 xl:grid-cols-[1.45fr_.85fr]">
      <div className="rounded-xl border border-white/8 bg-[#0c1b20] p-5"><div className="mb-5 flex flex-wrap items-start justify-between gap-3"><div><h3 className="font-medium text-white">Active data graph</h3><p className="mt-1 text-xs text-slate-500">{dataset ? `${dataset.provider} · ${dataset.storage.replaceAll('_', ' ')} · ${dataset.status}` : 'No active project dataset'}</p></div>{dataset && <Pill value={dataset.compatibility} />}</div>{network?.nodes.length ? <Graph nodes={network.nodes} dependencies={network.dependencies} hotNodeIds={prediction?.paths.map((path) => path.node.id) ?? []} /> : <Empty message="Choose and import a compatible dataset to construct the persistent dependency graph." action="Open Dataset Library" onAction={onOpenDataset} />}</div>
      <div className="rounded-xl border border-white/8 bg-[#0c1b20] p-5"><p className="font-mono text-[10px] uppercase tracking-[.16em] text-slate-500">System health</p><div className="mt-5 space-y-3">{health ? [['Database', health.database.status, `${health.database.latencyMs} ms`], ['API', health.api.status, 'route handler'], ['Dataset storage', health.datasetStorage.status, health.datasetStorage.mode], ['Cascade engine', health.cascadeEngine.status, health.cascadeEngine.model], ['Ingestion engine', health.ingestionEngine.status, 'server-side validation']].map(([label, state, detail]) => <div key={label} className="flex items-center justify-between gap-3 border-b border-white/6 pb-3 last:border-0"><div><p className="text-sm text-slate-200">{label}</p><p className="mt-1 text-[10px] text-slate-500">{detail}</p></div><Pill value={state} /></div>) : <p className="text-sm text-amber-200">Health check has not completed. Open the diagnostic window for recovery guidance.</p>}</div></div>
    </div>
    <div className="grid gap-6 xl:grid-cols-[1.15fr_.85fr]">
      <div className="rounded-xl border border-cyan-300/15 bg-cyan-300/[.035] p-5"><div className="flex gap-4"><div className="grid size-10 shrink-0 place-items-center rounded-xl border border-cyan-300/20 bg-cyan-300/10 text-cyan-300"><Activity className="size-5" /></div><div><div className="flex flex-wrap items-center gap-3"><h3 className="font-medium text-white">Explainable cascade reasoning</h3><span className="rounded-full bg-white/5 px-2 py-1 font-mono text-[9px] text-cyan-200">{dashboard?.model.name ?? 'MODEL UNAVAILABLE'}</span></div>{prediction ? <><p className="mt-3 text-sm leading-6 text-slate-300">{prediction.reasoning}</p><div className="mt-4 flex flex-wrap gap-2">{prediction.paths.slice(0, 5).map((path) => <span key={path.id} className="rounded-md border border-white/8 px-3 py-2 text-xs text-slate-300">T+{path.delayMinutes} · {path.node.name} · {percentage(path.probability)}</span>)}</div></> : <p className="mt-3 text-sm leading-6 text-slate-400">No cascade has been calculated for this workspace. Create a scenario after selecting a READY dataset.</p>}</div></div></div>
      <div className="rounded-xl border border-white/8 bg-[#0c1b20] p-5"><h3 className="font-medium text-white">Active scenario</h3>{dashboard?.activeScenario ? <><p className="mt-3 text-lg text-slate-200">{dashboard.activeScenario.name}</p><p className="mt-1 text-xs text-slate-500">Trigger severity {percentage(dashboard.activeScenario.triggerSeverity)} · {dashboard.activeScenario.events.length} event(s)</p><button onClick={() => onOpenScenario(dashboard.activeScenario!.id)} className="mt-5 flex w-full items-center justify-center gap-2 rounded-lg border border-white/10 py-3 text-xs text-slate-300 hover:bg-white/5">Open simulation <ArrowRight className="size-3.5" /></button></> : <p className="mt-3 text-sm text-slate-500">No scenario has been created for the active project.</p>}</div>
    </div>
  </div>
}

function MetricCard({ label, value, note, accent }: { label: string; value: string; note: string; accent?: string }) { return <div className="rounded-xl border border-white/8 bg-[#0c1b20] p-4"><div className="mb-5 flex justify-between"><span className="font-mono text-[10px] uppercase tracking-[.14em] text-slate-500">{label}</span>{accent === 'risk' ? <ShieldAlert className="size-4 text-red-300" /> : <Activity className="size-4 text-slate-500" />}</div><b className="text-2xl text-white">{value}</b><p className="mt-1 truncate text-[10px] text-slate-500">{note}</p></div> }

function Graph({ nodes, dependencies, hotNodeIds }: { nodes: Node[]; dependencies: Dependency[]; hotNodeIds: string[] }) { const layout = nodes.slice(0, 36).map((node, index) => ({ ...node, x: 10 + (index % 6) * 16, y: 15 + Math.floor(index / 6) * 20 })); const positions = new Map(layout.map((node) => [node.id, node])); return <div className="relative min-h-[360px] overflow-hidden rounded-lg border border-white/6 bg-[#081318]" style={{ backgroundImage: 'linear-gradient(rgba(90,140,150,.06) 1px, transparent 1px), linear-gradient(90deg, rgba(90,140,150,.06) 1px, transparent 1px)', backgroundSize: '32px 32px' }}><svg className="absolute inset-0 size-full" viewBox="0 0 100 100" preserveAspectRatio="none">{dependencies.slice(0, 90).map((edge) => { const from = positions.get(edge.fromNodeId); const to = positions.get(edge.toNodeId); if (!from || !to) return null; const hot = hotNodeIds.includes(edge.fromNodeId) && hotNodeIds.includes(edge.toNodeId); return <line key={edge.id} x1={from.x} y1={from.y} x2={to.x} y2={to.y} stroke={hot ? '#54d6dc' : '#42656b'} strokeWidth={hot ? '.75' : '.35'} strokeDasharray={hot ? '2 1' : '0'} /> })}</svg>{layout.map((node) => <div key={node.id} className="absolute -translate-x-1/2 -translate-y-1/2 text-center" style={{ left: `${node.x}%`, top: `${node.y}%` }}><span className={`mx-auto grid size-9 place-items-center rounded-full border-2 bg-[#0c1b20] ${hotNodeIds.includes(node.id) ? 'border-cyan-300 text-cyan-200' : 'border-white/20 text-slate-400'}`}><CircleDot className="size-3.5" /></span><span className="mt-1 block max-w-24 truncate text-[9px] text-slate-400">{node.name}</span></div>)}</div> }

function Empty({ message, action, onAction }: { message: string; action?: string; onAction?: () => void }) { return <div className="grid min-h-[240px] place-items-center p-8 text-center"><div><Database className="mx-auto size-7 text-slate-600" /><p className="mt-3 max-w-sm text-sm leading-6 text-slate-400">{message}</p>{action && onAction && <button onClick={onAction} className="mt-5 rounded-lg border border-white/10 px-3 py-2 text-xs text-slate-300 hover:bg-white/5">{action}</button>}</div></div> }

function DatasetLibrary({ datasets, selected, search, setSearch, busy, openDataset, onAction, refresh }: { datasets: Dataset[]; selected: DatasetDetail | null; search: string; setSearch: (value: string) => void; busy: string | null; openDataset: (id: string) => Promise<void>; onAction: (label: string, operation: () => Promise<void>) => Promise<void>; refresh: (includeCatalog?: boolean) => Promise<void> }) {
  const [mapping, setMapping] = useState<{ source?: string; target?: string; timestamp?: string; weight?: string }>({})
  const fields = selected?.schemas[0]?.fields ?? []
  useEffect(() => { if (selected?.mappings[0]?.mapping) setMapping(selected.mappings[0].mapping) }, [selected])
  const upload = async (event: ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; const body = new FormData(); body.append('file', file); await onAction('upload', async () => { await api('/api/datasets/upload', { method: 'POST', body }); await refresh(true) }); event.target.value = '' }
  const matching = useMemo(() => datasets.filter((dataset) => !search || `${dataset.name} ${dataset.description ?? ''} ${dataset.provider} ${dataset.category ?? ''}`.toLowerCase().includes(search.toLowerCase())), [datasets, search])
  return <div className="space-y-6"><SectionHeader eyebrow="Dataset platform" title="Dataset Library" description="Catalog metadata is stored first. Raw SNAP files and uploads are fetched and processed server-side only when requested."><div className="flex flex-wrap gap-2"><button onClick={() => void onAction('snap-catalog', async () => { await api('/api/datasets/snap/catalog', { method: 'POST' }) })} disabled={busy !== null} className="flex items-center gap-2 rounded-lg bg-cyan-300 px-4 py-2.5 text-xs font-semibold text-[#071014] disabled:opacity-50"><DownloadIcon busy={busy === 'snap-catalog'} />Load official SNAP catalog</button><label className="flex cursor-pointer items-center gap-2 rounded-lg border border-white/10 px-4 py-2.5 text-xs text-slate-300 hover:bg-white/5"><Upload className="size-3.5" />Upload dataset<input type="file" accept=".csv,.tsv,.json,.jsonl,.txt,.gz,.zip" className="hidden" onChange={upload} /></label></div></SectionHeader>
    <div className="grid gap-6 xl:grid-cols-[1.2fr_.8fr]"><div><div className="mb-4 flex gap-2"><div className="relative min-w-0 flex-1"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-slate-500" /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search name, description, category, provider" className="w-full rounded-lg border border-white/10 bg-white/5 py-2.5 pl-9 pr-3 text-xs text-white outline-none placeholder:text-slate-600" /></div><button onClick={() => void refresh(true)} className="rounded-lg border border-white/10 px-3 text-xs text-slate-300"><Search className="size-3.5" /></button></div><div className="grid gap-3">{matching.length ? matching.map((dataset) => <article key={dataset.id} className="rounded-xl border border-white/8 bg-[#0c1b20] p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><h3 className="truncate font-medium text-white">{dataset.name}</h3><Pill value={dataset.status} /></div><p className="mt-1 text-xs text-slate-500">{dataset.provider} · {dataset.category ?? 'Uncategorized'} · {dataset.isUserUpload ? 'USER UPLOADED' : dataset.isProjectCopy ? 'PROJECT COPY' : dataset.isCatalog ? 'PUBLIC CATALOG' : 'PERSISTED DATASET'}</p></div><Pill value={dataset.compatibility} /></div><div className="mt-4 grid grid-cols-3 gap-2 text-[10px] text-slate-500"><span>{number(dataset.nodeCount || dataset._count?.nodes)} nodes</span><span>{number(dataset.edgeCount || dataset._count?.dependencies)} edges</span><span>{dataset.isTemporal ? 'temporal' : 'static'} · {formatBytes(dataset.sizeBytes)}</span></div><div className="mt-4 flex flex-wrap gap-2"><button onClick={() => void openDataset(dataset.id)} className="rounded-lg border border-white/10 px-3 py-2 text-xs text-slate-300 hover:bg-white/5">{busy === `open-${dataset.id}` ? 'Opening…' : 'Open'}</button><button onClick={() => void onAction(`use-${dataset.id}`, async () => { await api(`/api/datasets/${dataset.id}/use`, { method: 'POST' }) })} disabled={dataset.compatibility === 'NOT_COMPATIBLE'} title={dataset.compatibility === 'NOT_COMPATIBLE' ? 'Map source and target fields first.' : undefined} className="rounded-lg border border-cyan-300/25 px-3 py-2 text-xs text-cyan-100 disabled:cursor-not-allowed disabled:opacity-45">Use in project</button>{dataset.isCatalog || dataset.status === 'AVAILABLE' ? <button onClick={() => void onAction(`download-${dataset.id}`, async () => { await api(`/api/datasets/${dataset.id}/download`, { method: 'POST' }) })} className="rounded-lg border border-white/10 px-3 py-2 text-xs text-slate-300">{busy === `download-${dataset.id}` ? 'Downloading…' : 'Download & import'}</button> : null}<button onClick={() => void onAction(`copy-${dataset.id}`, async () => { await api(`/api/datasets/${dataset.id}/copy`, { method: 'POST' }) })} className="rounded-lg border border-white/10 px-3 py-2 text-xs text-slate-300">Create project copy</button></div></article>) : <Empty message="No persisted datasets match this search. Load the official catalog or upload a supported graph file." />}</div></div>
      <aside className="h-fit rounded-xl border border-white/8 bg-[#0c1b20] p-5"><h3 className="font-medium text-white">{selected ? selected.name : 'Dataset inspector'}</h3>{selected ? <div className="mt-4 space-y-5"><div className="grid grid-cols-2 gap-3 text-xs"><Detail label="Provider" value={selected.provider} /><Detail label="Storage" value={selected.storage.replaceAll('_', ' ')} /><Detail label="Import status" value={selected.status} /><Detail label="Compatibility" value={selected.compatibility.replaceAll('_', ' ')} /></div><div className="rounded-lg border border-white/8 bg-white/[.025] p-3"><p className="font-mono text-[10px] uppercase tracking-wide text-slate-500">Provenance</p><p className="mt-2 text-xs leading-5 text-slate-300">{selected.isUserUpload ? 'USER UPLOADED — raw file and normalized records are separately tracked.' : selected.isProjectCopy ? 'PROJECT COPY — original source is preserved; edits target this version.' : selected.isCatalog ? 'PUBLIC CATALOG — official provider metadata; raw file is downloaded on demand.' : 'PERSISTED PROJECT DATASET'}</p></div>{fields.length ? <form onSubmit={(event: FormEvent) => { event.preventDefault(); void onAction(`mapping-${selected.id}`, async () => { await api(`/api/datasets/${selected.id}/mapping`, { method: 'POST', body: JSON.stringify({ mapping }) }); await openDataset(selected.id) }) }}><p className="font-mono text-[10px] uppercase tracking-wide text-slate-500">Schema mapping</p><p className="mt-1 text-xs text-slate-400">Confirm fields before normalizing. No missing relationship is silently assumed.</p><div className="mt-3 grid gap-2"><MappingSelect label="Source node" value={mapping.source} fields={fields} onChange={(value) => setMapping((current) => ({ ...current, source: value }))} /><MappingSelect label="Target node" value={mapping.target} fields={fields} onChange={(value) => setMapping((current) => ({ ...current, target: value }))} /><MappingSelect label="Event time" value={mapping.timestamp} fields={fields} optional onChange={(value) => setMapping((current) => ({ ...current, timestamp: value }))} /><MappingSelect label="Strength" value={mapping.weight} fields={fields} optional onChange={(value) => setMapping((current) => ({ ...current, weight: value }))} /></div><button type="submit" className="mt-3 w-full rounded-lg bg-cyan-300 py-2.5 text-xs font-semibold text-[#071014]">Save mapping and normalize</button></form> : <p className="text-sm leading-6 text-slate-500">Open a downloaded or uploaded data file to inspect detected fields and map it.</p>}<div><p className="font-mono text-[10px] uppercase tracking-wide text-slate-500">Import history</p>{selected.imports.length ? selected.imports.map((record) => <p key={record.id} className="mt-2 text-xs text-slate-400"><Pill value={record.status} /> <span className="ml-2">{number(record.rowCount)} records · {formatBytes(record.bytesRead)}</span></p>) : <p className="mt-2 text-xs text-slate-500">No raw file has been imported.</p>}</div></div> : <p className="mt-3 text-sm leading-6 text-slate-500">Open a dataset to view source metadata, raw-file import history, schema fields, and mapping controls.</p>}</aside>
    </div>
  </div>
}

function DownloadIcon({ busy }: { busy: boolean }) { return busy ? <Loader2 className="size-3.5 animate-spin" /> : <Database className="size-3.5" /> }
function Detail({ label, value }: { label: string; value: string }) { return <div><p className="text-slate-500">{label}</p><p className="mt-1 truncate text-slate-200">{value}</p></div> }
function MappingSelect({ label, value, fields, optional, onChange }: { label: string; value?: string; fields: Array<{ name: string; inferredType: string }>; optional?: boolean; onChange: (value: string | undefined) => void }) { return <label className="grid grid-cols-[.75fr_1fr] items-center gap-2 text-xs text-slate-400"><span>{label}</span><select value={value ?? ''} onChange={(event) => onChange(event.target.value || undefined)} className="min-w-0 rounded border border-white/10 bg-[#09161a] px-2 py-2 text-xs text-slate-200"><option value="">{optional ? 'Not mapped' : 'Choose field'}</option>{fields.map((field) => <option key={field.name} value={field.name}>{field.name} · {field.inferredType}</option>)}</select></label> }

function NetworkEditor({ network, activeDataset, onAction }: { network: { nodes: Node[]; dependencies: Dependency[] } | null; activeDataset: Dashboard['activeDataset']; onAction: (label: string, operation: () => Promise<void>) => Promise<void> }) {
  const [nodeForm, setNodeForm] = useState({ name: '', code: '', criticality: '0.5', capacity: '100', health: '1', currentLoad: '0' })
  const [edgeForm, setEdgeForm] = useState({ fromNodeId: '', toNodeId: '', relationship: 'dependency', strength: '0.7', propagationProbability: '0.7', propagationDelay: '5' })
  if (!activeDataset || !network) return <Empty message="A compatible active dataset is required before the persistent network editor is available." />
  return <div className="space-y-6"><SectionHeader eyebrow="Project network" title="Network Editor" description="Nodes and dependencies are changed through the server API and persisted to the active project dataset. Create a project copy before editing an imported source."><Pill value={activeDataset.isProjectCopy ? 'PROJECT COPY' : activeDataset.isUserUpload ? 'USER DATASET' : 'SOURCE DATASET'} /></SectionHeader><div className="grid gap-6 xl:grid-cols-[1.1fr_.9fr]"><div className="rounded-xl border border-white/8 bg-[#0c1b20] p-5"><h3 className="font-medium text-white">Visual graph</h3><p className="mt-1 text-xs text-slate-500">{number(network.nodes.length)} nodes · {number(network.dependencies.length)} dependencies · persisted PostgreSQL graph</p><div className="mt-5"><Graph nodes={network.nodes} dependencies={network.dependencies} hotNodeIds={[]} /></div></div><div className="space-y-5"><form onSubmit={(event) => { event.preventDefault(); void onAction('create-node', async () => { await api('/api/nodes', { method: 'POST', body: JSON.stringify({ datasetId: activeDataset.id, ...nodeForm, criticality: Number(nodeForm.criticality), capacity: Number(nodeForm.capacity), health: Number(nodeForm.health), currentLoad: Number(nodeForm.currentLoad) }) }); setNodeForm({ name: '', code: '', criticality: '0.5', capacity: '100', health: '1', currentLoad: '0' }) }) }} className="rounded-xl border border-white/8 bg-[#0c1b20] p-5"><h3 className="font-medium text-white">Add node</h3><div className="mt-4 grid gap-2 sm:grid-cols-2">{Object.entries(nodeForm).map(([key, value]) => <input key={key} required value={value} onChange={(event) => setNodeForm((current) => ({ ...current, [key]: event.target.value }))} placeholder={key.replace(/([A-Z])/g, ' $1')} className="rounded-lg border border-white/10 bg-white/5 px-3 py-2 text-xs text-white placeholder:text-slate-600" />)}</div><button className="mt-3 w-full rounded-lg bg-cyan-300 py-2.5 text-xs font-semibold text-[#071014]">Persist node</button></form><form onSubmit={(event) => { event.preventDefault(); void onAction('create-dependency', async () => { await api('/api/dependencies', { method: 'POST', body: JSON.stringify({ datasetId: activeDataset.id, ...edgeForm, strength: Number(edgeForm.strength), propagationProbability: Number(edgeForm.propagationProbability), propagationDelay: Number(edgeForm.propagationDelay) }) }); setEdgeForm((current) => ({ ...current, fromNodeId: '', toNodeId: '' })) }) }} className="rounded-xl border border-white/8 bg-[#0c1b20] p-5"><h3 className="font-medium text-white">Add dependency</h3><div className="mt-4 grid gap-2"><select required value={edgeForm.fromNodeId} onChange={(event) => setEdgeForm((current) => ({ ...current, fromNodeId: event.target.value }))} className="rounded-lg border border-white/10 bg-[#09161a] px-3 py-2 text-xs text-white"><option value="">Source node</option>{network.nodes.map((node) => <option key={node.id} value={node.id}>{node.name}</option>)}</select><select required value={edgeForm.toNodeId} onChange={(event) => setEdgeForm((current) => ({ ...current, toNodeId: event.target.value }))} className="rounded-lg border border-white/10 bg-[#09161a] px-3 py-2 text-xs text-white"><option value="">Target node</option>{network.nodes.map((node) => <option key={node.id} value={node.id}>{node.name}</option>)}</select>{(['relationship', 'strength', 'propagationProbability', 'propagationDelay'] as const).map((key) => <input key={key} required value={edgeForm[key]} onChange={(event) => setEdgeForm((current) => ({ ...current, [key]: event.target.value }))} placeholder={key.replace(/([A-Z])/g, ' $1')} className="rounded-lg border border-white/10 bg-white/5 px-3 py-2 text-xs text-white placeholder:text-slate-600" />)}</div><button className="mt-3 w-full rounded-lg border border-cyan-300/25 py-2.5 text-xs text-cyan-100">Persist dependency</button></form></div></div><div className="overflow-hidden rounded-xl border border-white/8 bg-[#0c1b20]"><div className="border-b border-white/8 px-5 py-4"><h3 className="font-medium text-white">Table editor</h3></div><div className="max-h-80 overflow-auto"><table className="w-full text-left text-xs"><thead className="sticky top-0 bg-[#0c1b20] text-slate-500"><tr><th className="px-5 py-3">Node</th><th className="px-3 py-3">Health</th><th className="px-3 py-3">Load / Capacity</th><th className="px-3 py-3">Criticality</th><th className="px-5 py-3">State</th></tr></thead><tbody>{network.nodes.map((node) => <tr key={node.id} className="border-t border-white/6"><td className="px-5 py-3 text-slate-200">{node.name}<span className="ml-2 font-mono text-[10px] text-slate-600">{node.code}</span></td><td className="px-3 py-3 text-slate-400">{percentage(node.health)}</td><td className="px-3 py-3 text-slate-400">{node.currentLoad} / {node.capacity}</td><td className="px-3 py-3 text-slate-400">{percentage(node.criticality)}</td><td className="px-5 py-3"><Pill value={node.status} /></td></tr>)}</tbody></table></div></div></div>
}

function Simulator({ dashboard, network, scenario, setScenario, busy, onAction, openScenario }: { dashboard: Dashboard | null; network: { nodes: Node[]; dependencies: Dependency[] } | null; scenario: ScenarioDetail | null; setScenario: (value: ScenarioDetail | null) => void; busy: string | null; onAction: (label: string, operation: () => Promise<void>) => Promise<void>; openScenario: (id: string) => Promise<void> }) {
  const [form, setForm] = useState({ name: '', nodeId: '', severity: '0.8', triggerType: 'FAILURE', durationMinutes: '30', affectedParameter: 'availability' })
  const chosenScenario = scenario ?? null
  if (!dashboard?.activeDataset || !network) return <Empty message="Select a READY dataset, then create a scenario using one of its persisted network nodes." />
  return <div className="space-y-6"><SectionHeader eyebrow="Explainable simulation" title="Cascade Simulator" description="The simulation snapshots the selected dataset and writes every run, affected node, path, and explanation to PostgreSQL."><Pill value={dashboard.model.name} /></SectionHeader><div className="grid gap-6 xl:grid-cols-[.8fr_1.2fr]"><form onSubmit={(event) => { event.preventDefault(); void onAction('create-scenario', async () => { const created = await api<{ id: string }>('/api/scenarios', { method: 'POST', body: JSON.stringify({ ...form, severity: Number(form.severity), durationMinutes: Number(form.durationMinutes) }) }); await openScenario(created.id); setForm((current) => ({ ...current, name: '' })) }) }} className="rounded-xl border border-white/8 bg-[#0c1b20] p-5"><h3 className="font-medium text-white">Create scenario</h3><p className="mt-1 text-xs text-slate-500">Active data: {dashboard.activeDataset.name} · {dashboard.activeDataset.provider}</p><div className="mt-4 grid gap-3"><input required value={form.name} onChange={(event) => setForm((current) => ({ ...current, name: event.target.value }))} placeholder="Scenario name" className="rounded-lg border border-white/10 bg-white/5 px-3 py-2.5 text-xs text-white placeholder:text-slate-600" /><select required value={form.nodeId} onChange={(event) => setForm((current) => ({ ...current, nodeId: event.target.value }))} className="rounded-lg border border-white/10 bg-[#09161a] px-3 py-2.5 text-xs text-white"><option value="">Trigger node</option>{network.nodes.map((node) => <option key={node.id} value={node.id}>{node.name}</option>)}</select><div className="grid grid-cols-2 gap-3"><select value={form.triggerType} onChange={(event) => setForm((current) => ({ ...current, triggerType: event.target.value }))} className="rounded-lg border border-white/10 bg-[#09161a] px-3 py-2.5 text-xs text-white">{['FAILURE', 'DEGRADATION', 'OVERLOAD', 'ANOMALY', 'MAINTENANCE'].map((type) => <option key={type}>{type}</option>)}</select><input type="number" min="0.05" max="1" step="0.05" value={form.severity} onChange={(event) => setForm((current) => ({ ...current, severity: event.target.value }))} aria-label="Trigger severity" className="rounded-lg border border-white/10 bg-white/5 px-3 py-2.5 text-xs text-white" /></div><div className="grid grid-cols-2 gap-3"><input type="number" min="1" value={form.durationMinutes} onChange={(event) => setForm((current) => ({ ...current, durationMinutes: event.target.value }))} placeholder="Duration minutes" className="rounded-lg border border-white/10 bg-white/5 px-3 py-2.5 text-xs text-white" /><input value={form.affectedParameter} onChange={(event) => setForm((current) => ({ ...current, affectedParameter: event.target.value }))} placeholder="Affected parameter" className="rounded-lg border border-white/10 bg-white/5 px-3 py-2.5 text-xs text-white" /></div></div><button className="mt-4 flex w-full items-center justify-center gap-2 rounded-lg bg-cyan-300 py-3 text-xs font-semibold text-[#071014]"><Play className="size-3.5" />Create persisted scenario</button></form><div className="rounded-xl border border-white/8 bg-[#0c1b20] p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><h3 className="font-medium text-white">{chosenScenario ? chosenScenario.name : 'Select a scenario'}</h3><p className="mt-1 text-xs text-slate-500">{chosenScenario ? `Trigger severity ${percentage(chosenScenario.triggerSeverity)} · ${chosenScenario.events.map((event) => event.node.name).join(', ')}` : 'Choose a saved scenario from history.'}</p></div>{chosenScenario && <div className="flex gap-2"><button onClick={() => void onAction('run-cascade', async () => { await api('/api/cascade/run', { method: 'POST', body: JSON.stringify({ scenarioId: chosenScenario.id }) }); await openScenario(chosenScenario.id) })} className="rounded-lg bg-cyan-300 px-3 py-2 text-xs font-semibold text-[#071014]">{busy === 'run-cascade' ? 'Running…' : 'Run baseline'}</button><button onClick={() => void onAction('calculate-interventions', async () => { await api('/api/interventions/calculate', { method: 'POST', body: JSON.stringify({ scenarioId: chosenScenario.id }) }); await openScenario(chosenScenario.id) })} className="rounded-lg border border-white/10 px-3 py-2 text-xs text-slate-300">Calculate interventions</button></div>}</div>{chosenScenario ? <SimulationResults scenario={chosenScenario} onAction={onAction} reopen={openScenario} /> : <Empty message="Create a scenario or open a prior scenario to run a persisted cascade." />}</div></div><div className="rounded-xl border border-white/8 bg-[#0c1b20] p-5"><h3 className="font-medium text-white">Saved scenarios</h3><div className="mt-3 grid gap-2 md:grid-cols-2 xl:grid-cols-3">{dashboard.scenarios.map((saved) => <button key={saved.id} onClick={() => void openScenario(saved.id)} className={`rounded-lg border p-3 text-left ${chosenScenario?.id === saved.id ? 'border-cyan-300/35 bg-cyan-300/5' : 'border-white/8 hover:bg-white/[.03]'}`}><p className="truncate text-sm text-slate-200">{saved.name}</p><p className="mt-1 text-[10px] text-slate-500">{percentage(saved.triggerSeverity)} trigger · {saved.predictions[0] ? `${percentage(saved.predictions[0].probability)} cascade` : 'not yet run'}</p></button>)}</div></div></div>
}

function SimulationResults({ scenario, onAction, reopen }: { scenario: ScenarioDetail; onAction: (label: string, operation: () => Promise<void>) => Promise<void>; reopen: (id: string) => Promise<void> }) { const latestRun = scenario.runs[0]; const latestPrediction = scenario.predictions[0]; return <div className="mt-5 space-y-5">{latestPrediction ? <div className="rounded-lg border border-cyan-300/15 bg-cyan-300/[.035] p-4"><div className="flex flex-wrap justify-between gap-4"><div><p className="font-mono text-[10px] uppercase tracking-wide text-cyan-200">Latest calculation</p><p className="mt-2 text-2xl font-semibold text-white">{percentage(latestPrediction.probability)} cascade probability</p></div><div className="grid grid-cols-2 gap-x-5 gap-y-1 text-xs text-slate-400"><span>Risk score</span><b className="text-slate-200">{latestPrediction.riskScore.toFixed(2)}</b><span>Critical endpoints</span><b className="text-slate-200">{latestPrediction.criticalEndpoints}</b><span>Time to impact</span><b className="text-slate-200">T+{latestPrediction.timeToImpact}</b></div></div><p className="mt-3 text-xs leading-5 text-slate-300">{latestPrediction.reasoning}</p></div> : null}{latestRun ? <div><p className="font-mono text-[10px] uppercase tracking-wide text-slate-500">Propagation timeline</p><div className="mt-3 max-h-64 space-y-2 overflow-auto">{latestRun.results.filter((result) => result.affected).sort((a, b) => a.timeOffset - b.timeOffset).map((result) => <div key={result.id} className="flex gap-3 rounded-lg border border-white/8 bg-white/[.02] p-3"><span className="w-10 shrink-0 font-mono text-[10px] text-slate-500">T+{result.timeOffset}</span><span className="mt-1 size-2 shrink-0 rounded-full bg-cyan-300" /><div className="min-w-0"><p className="text-sm text-slate-200">{result.node.name} <span className="ml-2 font-mono text-[10px] text-amber-200">{percentage(result.probability)}</span></p><p className="mt-1 text-xs leading-5 text-slate-500">{result.reason}</p></div></div>)}</div></div> : null}{scenario.interventions.length ? <div><p className="font-mono text-[10px] uppercase tracking-wide text-slate-500">Intervention candidates</p><div className="mt-3 grid gap-3 md:grid-cols-2">{scenario.interventions.slice(0, 4).map((intervention) => <div key={intervention.id} className="rounded-lg border border-white/8 p-4"><div className="flex items-start justify-between gap-3"><p className="text-sm text-slate-200">{intervention.name}</p><Pill value={intervention.status} /></div><p className="mt-2 text-xs leading-5 text-slate-500">{intervention.candidates[0]?.rationale}</p><div className="mt-3 flex items-center justify-between text-xs"><span className="text-emerald-300">{intervention.candidates[0]?.riskReduction.toFixed(2)} risk reduction</span><span className="text-slate-500">score {intervention.candidates[0]?.score.toFixed(2)}</span></div>{intervention.status === 'PROPOSED' ? <button onClick={() => void onAction(`apply-${intervention.id}`, async () => { await api(`/api/interventions/${intervention.id}/apply`, { method: 'POST' }); await reopen(scenario.id) })} className="mt-3 w-full rounded-lg border border-cyan-300/25 py-2 text-xs text-cyan-100">Apply and simulate again</button> : null}</div>)}</div></div> : null}</div> }

function ScenarioHistory({ dashboard, onOpenScenario }: { dashboard: Dashboard | null; onOpenScenario: (id: string) => Promise<void> }) { return <div className="space-y-6"><SectionHeader eyebrow="Persistent history" title="Scenario History" description="Each completed run is stored with its inputs, model version, results, and path explanation. Reloading does not discard it." /><div className="rounded-xl border border-white/8 bg-[#0c1b20] p-5">{dashboard?.recentRuns.length ? dashboard.recentRuns.map((run) => <div key={run.id} className="flex flex-wrap items-center justify-between gap-4 border-b border-white/6 py-4 last:border-0"><div><p className="text-sm text-white">{run.scenario.name}</p><p className="mt-1 text-xs text-slate-500">{run.modelName} · {new Date(run.startedAt).toLocaleString()} · {run.results.length} affected nodes · {run.isBaseline ? 'baseline' : 'intervention run'}</p></div><button onClick={() => void onOpenScenario(run.scenario.id)} className="rounded-lg border border-white/10 px-3 py-2 text-xs text-slate-300">Open scenario</button></div>) : <Empty message="No persisted simulations have completed yet." />}</div></div> }

function Diagnostics({ diagnostics, onOpen }: { diagnostics: Diagnostic[]; onOpen: (entry: Diagnostic) => void }) { return <div className="space-y-6"><SectionHeader eyebrow="System observability" title="Diagnostics Center" description="Serious server errors are persisted as ErrorEvent records without passwords, connection strings, or API keys." /><div className="rounded-xl border border-white/8 bg-[#0c1b20] p-5">{diagnostics.length ? diagnostics.map((entry) => <button key={entry.id} onClick={() => onOpen(entry)} className="flex w-full flex-wrap items-center justify-between gap-3 border-b border-white/6 py-4 text-left last:border-0"><div><div className="flex items-center gap-2"><Pill value={entry.severity} /><p className="text-sm text-slate-200">{entry.message}</p></div><p className="mt-2 text-xs text-slate-500">{entry.component} · {entry.operation} · {new Date(entry.createdAt).toLocaleString()}</p></div><ArrowRight className="size-4 text-slate-500" /></button>) : <Empty message="No unresolved diagnostic events are stored in the active workspace." />}</div></div> }

function DiagnosticWindow({ diagnostic, onClose }: { diagnostic: ApiError | Diagnostic; onClose: () => void }) { const entry = diagnostic as Diagnostic; const apiError = diagnostic as ApiError; const severity = entry.severity ?? 'ERROR'; const message = entry.message; const details = entry.parameters ?? apiError.details; const suggestions = entry.suggestedFix ? [entry.suggestedFix] : apiError.suggestedActions ?? []; return <div className="fixed inset-0 z-50 grid place-items-center bg-black/70 p-4 backdrop-blur-sm" role="dialog" aria-modal="true" aria-label="Diagnostic alert"><div className={`w-full max-w-2xl overflow-hidden rounded-2xl border bg-[#0b171b] shadow-2xl ${severity === 'CRITICAL' ? 'border-red-300/60' : 'border-amber-300/35'}`}><div className={`flex items-start justify-between gap-4 border-b p-5 ${severity === 'CRITICAL' ? 'border-red-300/25 bg-red-300/10' : 'border-amber-300/15 bg-amber-300/[.05]'}`}><div className="flex gap-3"><AlertTriangle className={severity === 'CRITICAL' ? 'size-6 text-red-200' : 'size-6 text-amber-200'} /><div><p className="font-mono text-[10px] uppercase tracking-[.2em] text-slate-400">{severity} diagnostic</p><h2 className="mt-1 text-lg font-semibold text-white">{message}</h2></div></div><button onClick={onClose} className="rounded-lg p-2 text-slate-400 hover:bg-white/5 hover:text-white" aria-label="Close diagnostic"><X className="size-5" /></button></div><div className="space-y-5 p-5"><DiagnosticBlock title="What happened"><p>{message}</p></DiagnosticBlock><DiagnosticBlock title="Failing operation"><p>{entry.operation ?? 'API request'} · {entry.component ?? 'Server API'}</p>{apiError.requestId || entry.requestId ? <p className="mt-1 font-mono text-[10px] text-slate-500">Request ID: {apiError.requestId ?? entry.requestId}</p> : null}</DiagnosticBlock>{details && Object.keys(details).length ? <DiagnosticBlock title="Relevant parameters"><dl className="grid gap-2 sm:grid-cols-2">{Object.entries(details).map(([key, value]) => <div key={key} className="rounded-md border border-white/8 bg-white/[.025] px-3 py-2"><dt className="font-mono text-[9px] uppercase text-slate-500">{key}</dt><dd className="mt-1 break-words text-xs text-slate-300">{typeof value === 'object' ? JSON.stringify(value) : String(value)}</dd></div>)}</dl></DiagnosticBlock> : null}<DiagnosticBlock title="Why this happened"><p>{entry.technicalDetails ?? 'The server returned a structured error response. Sensitive connection details are intentionally excluded.'}</p></DiagnosticBlock><DiagnosticBlock title="Recommended next action">{suggestions.length ? <ul className="space-y-2">{suggestions.map((suggestion) => <li key={suggestion} className="flex gap-2"><CheckCircle2 className="mt-0.5 size-3.5 shrink-0 text-cyan-300" />{suggestion}</li>)}</ul> : <p>Retry after reviewing the operation and its parameters.</p>}</DiagnosticBlock><div className="flex justify-end"><button onClick={onClose} className="rounded-lg bg-cyan-300 px-4 py-2.5 text-xs font-semibold text-[#071014]">Acknowledge</button></div></div></div></div> }
function DiagnosticBlock({ title, children }: { title: string; children: React.ReactNode }) { return <section><p className="font-mono text-[10px] uppercase tracking-[.16em] text-cyan-200">{title}</p><div className="mt-2 text-sm leading-6 text-slate-300">{children}</div></section> }
